package com.ashkan.hotel;
import java.math.*;import java.nio.file.*;import java.time.*;
public final class CampaignServiceSmokeTest{
 public static void main(String[]a)throws Exception{Path f=Files.createTempDirectory("campaign-test").resolve("campaign.tsv");Clock clock=Clock.fixed(Instant.parse("2026-10-30T09:00:00Z"),ZoneId.of("UTC"));CrmService crm=new CrmService(f.resolveSibling("crm.tsv"),clock);crm.saveGuest(new CrmService.Guest("G1","Guest","g@example.com","1","",false));crm.adjustPoints("G1",600,"test");CampaignService c=new CampaignService(f,clock);c.save(new CampaignService.Campaign("WELCOME","Welcome",CampaignService.DiscountType.PERCENT,new BigDecimal("15"),new BigDecimal("20"),new BigDecimal("50"),LocalDate.of(2026,10,1),LocalDate.of(2026,11,30),1,CrmService.Tier.SILVER,true));check(c.preview("welcome","G1",new BigDecimal("100"),crm).compareTo(new BigDecimal("15.00"))==0,"percentage preview");CampaignService.Redemption r=c.redeem("WELCOME","G1",new BigDecimal("100"),crm);check(r.discount().compareTo(new BigDecimal("15.00"))==0,"redeem");expect(IllegalStateException.class,()->c.redeem("WELCOME","G1",new BigDecimal("100"),crm));CampaignService loaded=new CampaignService(f,clock);check(loaded.usage("WELCOME")==1,"usage persisted");check(loaded.totalDiscounts().compareTo(new BigDecimal("15.00"))==0,"discount totals");check(loaded.csv().contains("WELCOME"),"CSV");expect(IllegalStateException.class,()->loaded.preview("WELCOME","G1",new BigDecimal("10"),crm));System.out.println("CampaignServiceSmokeTest: OK");}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static void expect(Class<? extends Throwable>t,Run r){try{r.run();throw new AssertionError("Expected "+t);}catch(Throwable e){if(!t.isInstance(e))throw new AssertionError(e);}}interface Run{void run()throws Exception;}}
